#define WIN32_LEAN_AND_MEAN
#include <windows.h>
#include <stdio.h>
static HWND dialog;
static unsigned enabled, destroyed;
static LRESULT CALLBACK window_proc(HWND w, UINT m, WPARAM a, LPARAM b)
{
    if (m == WM_CANCELMODE && dialog) {
        ++enabled;
        DestroyWindow(dialog);
    }
    if (m == WM_NCDESTROY && w == dialog) ++destroyed;
    return DefWindowProcW(w,m,a,b);
}
int main(void)
{
    WNDCLASSW cls = {0}; HWND owner;
    cls.lpfnWndProc=window_proc; cls.hInstance=GetModuleHandleW(NULL);
    cls.lpszClassName=L"P227CancelMode";
    if (!RegisterClassW(&cls)) return 2;
    owner=CreateWindowW(cls.lpszClassName,L"",WS_POPUP,0,0,1,1,0,0,cls.hInstance,0);
    if (!owner) return 3;
    EnableWindow(owner,FALSE);
    dialog=CreateWindowW(cls.lpszClassName,L"",WS_POPUP,0,0,1,1,owner,0,cls.hInstance,0);
    if (!dialog) return 4;
    SendMessageW(owner,WM_CANCELMODE,0,0);
    printf("enabled=%u destroyed=%u dialog_alive=%d owner_alive=%d\n",
        enabled,destroyed,IsWindow(dialog),IsWindow(owner));
    DestroyWindow(owner);
    return enabled==1 && destroyed==1 && !IsWindow(dialog) ? 0:1;
}

