#include <windows.h>
#include <stdio.h>
static unsigned callbacks;
static INT_PTR CALLBACK app(HWND w,UINT m,WPARAM a,LPARAM b)
{(void)w;(void)m;(void)a;(void)b;++callbacks;return FALSE;}
int main(void)
{
    WNDCLASSW c={0};unsigned mode;
    c.lpfnWndProc=DefWindowProcW;c.cbWndExtra=DLGWINDOWEXTRA;
    c.hInstance=GetModuleHandleW(NULL);c.lpszClassName=L"P227NativeInit";
    if(!RegisterClassW(&c))return 2;
    for(mode=0;mode<2;++mode){
        HWND w=CreateWindowW(c.lpszClassName,L"",WS_POPUP,0,0,1,1,0,0,c.hInstance,0);
        LONG before,after,result;LRESULT notify;
        if(!w)return 3;
        callbacks=0;
        if(mode)DefDlgProcW(w,WM_NULL,0,0);
        SetWindowLongW(w,DWL_DLGPROC,(LONG)app);
        SetWindowLongW(w,DWL_MSGRESULT,0x3141);
        before=GetWindowLongW(w,DWL_DLGPROC);
        notify=DefDlgProcW(w,WM_NOTIFYFORMAT,0,NF_QUERY);
        after=GetWindowLongW(w,DWL_DLGPROC);
        result=GetWindowLongW(w,DWL_MSGRESULT);
        printf("initialized=%u proc_before=%08lx proc_after=%08lx msgresult=%08lx notify=%ld callbacks=%u\n",mode,before,after,result,(long)notify,callbacks);
        SetWindowLongW(w,DWL_DLGPROC,0);
        DefDlgProcW(w,WM_NCDESTROY,0,0);DestroyWindow(w);
    }
    UnregisterClassW(c.lpszClassName,c.hInstance);return 0;
}
